package com.wizzadrds.theworldremembers;
import com.wizzadrds.theworldremembers.behavior.*; import com.wizzadrds.theworldremembers.relationship.*; import com.wizzadrds.theworldremembers.stress.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes;
public final class NpcLiveBehaviorGameTest { @GameTest public void trustedFollowIsRealNavigation(GameTestHelper c){var p=c.makeMockPlayer();var v=c.spawn(EntityTypes.VILLAGER,2,1,2);var rm=RelationshipManager.get(c.getLevel().getServer());rm.apply(new MemoryEvent(v.getUUID(),p.getUUID(),com.wizzadrds.theworldremembers.memory.MemoryEventType.PLAYER_GAVE_BREAD,1,com.wizzadrds.theworldremembers.memory.MemoryImportance.IMPORTANT));var am=NpcActivityManager.get(c.getLevel().getServer());am.set(v.getUUID(),NpcActivity.FOLLOWING_PLAYER,p.getUUID());c.runAtTickTime(2,()->{if(v.getNavigation().isDone()){c.fail("Villager did not navigate toward follow target");return;}c.succeed();});}}
